function mediaHintScore(entity,mediaType){const description=Object.values(entity?.descriptions||{}).map(item=>item?.value).join(' ').toLowerCase(),hints={FILM:['film','movie','영화'],TV:['television','tv series','series','텔레비전','드라마'],BOOK:['novel','book','literary','소설','책','문학'],ANIME:['anime','animation','animated','애니메이션']}[mediaType]||[];return hints.some(hint=>description.includes(hint))?0.2:0}
